def calculator(expr):
    return eval(expr)

def get_weather(city):
    return f"{city}: 22C, partly cloudy"

def get_time(city):
    return f"{city}: 14:30 UTC"

def agent(task):
    if task.startswith("calc:"):
        arg = task.split(":", 1)[1].strip()
        result = calculator(arg)
    elif task.startswith("weather:"):
        arg = task.split(":", 1)[1].strip()
        result = get_weather(arg)
    elif task.startswith("time:"):
        arg = task.split(":", 1)[1].strip()
        result = get_time(arg)
    else:
        result = "Unknown command"
    return {"task": task, "result": result}
